 import { supabase } from '../lib/supabase'

export async function checkUserSubscription(userId) {
    if (!userId) return false

    try {
        // 1. FIRST: Check if the user is an admin (Admins bypass payment)
        const { data: profile, error: profileError } = await supabase
            .from('profiles')
            .select('role')
            .eq('id', userId)
            .single()

        if (profileError) throw profileError

        // ✅ If the user is an admin, they get full access for free!
        if (profile?.role === 'admin') {
            return true
        }

        // 2. If not admin, check for a valid premium subscription
        const { data, error } = await supabase
            .from('subscription_payments')
            .select('id, expires_at, created_at')
            .eq('user_id', userId)
            .eq('type', 'premium')
            .eq('status', 'success')
            .order('created_at', { ascending: false })
            .limit(1)
            .maybeSingle()

        if (error) throw error
        if (!data) return false

        if (data.expires_at) {
            const now = new Date()
            const expiry = new Date(data.expires_at)
            if (expiry < now) return false
            return true
        }

        const created = new Date(data.created_at)
        const expiry = new Date(created)
        expiry.setDate(expiry.getDate() + 30)
        return expiry > new Date()
    } catch (error) {
        console.error('Error checking subscription:', error)
        return false
    }
}
